    'note.replyTitle': ['{name} replied to your post', '{name} iu përgjigj postimit tënd', '{name} hat auf deinen Beitrag geantwortet', '{name} je odgovorio na tvoju objavu'],
    'note.replyText': ['Open the MBG Board to read it.', 'Hape Tabelën MBG për ta lexuar.', 'Öffne die MBG-Pinnwand, um sie zu lesen.', 'Otvori MBG tablu da pročitaš.'],
